function arduino(){const g=new T.Group();box(g,2.35,.12,3.25,0,.08,0,C.pcb);for(const x of [-1.01,1.01])for(const z of [-1.42,1.42]){cyl(g,.09,.015,x,.148,z,C.gold);cyl(g,.045,.02,x,.16,z,C.black)}headers(g,-1,0,16);headers(g,1,.2,12);box(g,.7,.35,.65,-.42,.29,-1.35,C.metal);box(g,.5,.23,.025,-.42,.29,-1.69,C.black);box(g,.45,.4,.6,.56,.32,-1.32,C.black);box(g,.43,.2,1.35,.26,.25,.35,C.black);for(let i=0;i<12;i++)for(const x of [-.02,.54])box(g,.13,.06,.04,x,.19,-.23+i*.105,C.metal);box(g,.45,.11,.5,-.38,.2,-.45,C.black);for(const x of [.66,.89])cyl(g,.12,.3,x,.27,-.72,C.metal);for(let i=0;i<6;i++)box(g,.13,.05,.07,-.48,.18,.4+i*.15,C.gold);label(g,'ARDUINO',-.1,.152,1.13,.25);label(g,'DIGITAL',-.8,.152,-.15,.1);return g}
